        if(track instanceof THREE.QuaternionKeyframeTrack){
          const qa=new THREE.Quaternion(a[0],a[1],a[2],a[3]),qb=new THREE.Quaternion(b[0],b[1],b[2],b[3]);if(qa.dot(qb)<0)qb.set(-qb.x,-qb.y,-qb.z,-qb.w);qa.slerp(qb,.5).normalize();values=[qa.x,qa.y,qa.z,qa.w];
        }else values=Array.from(a,(v,i)=>(Number(v)+Number(b[i]??v))*.5);
