  function close(returnTopGames=false){stopWorld();if(persistTimer)persist();closeModal();window.removeEventListener('keydown',onKeyDown);window.removeEventListener('keyup',onKeyUp);window.removeEventListener('mousemove',onMouseMove);window.removeEventListener('mousedown',onMouseDown);window.removeEventListener('mouseup',onMouseUp);window.removeEventListener('contextmenu',onContextMenu);document.removeEventListener('pointerlockchange',onPointerLockChange);resetInputs();try{document.exitPointerLock?.();}catch{}UI.overlay?.remove();UI.overlay=null;UI.body=null;document.body.classList.remove('egoshoot-kl-open');if(returnTopGames)setTimeout(()=>window.JKGamesOpenTopGames?.(UI.sourcePhone),80);}
