  function renderGenderChoice(){stopWorld();UI.body.innerHTML=`<section class="eskl-choice"><small>CHARAKTER</small><h2>Wähle deinen Online-Charakter</h2><p>Du spielst selbst ausschließlich in Ego-Perspektive. Andere Spieler sehen diesen Charakter samt aktuell gehaltener Waffe.</p><div class="eskl-choice-grid"><button data-gender="man"><b>♂ Mann</b><small>Online-Modell</small></button><button data-gender="woman"><b>♀ Frau</b><small>Online-Modell</small></button></div></section>`;UI.body.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{state().gender=b.dataset.gender;persist();startLobby();});}

  function openInfo(){showModal(`<div class="eskl-modal-head"><div><small>V510 · FPS REBUILD</small><h2>Egoshoot.KL</h2></div><button data-modal-close>×</button></div><div class="eskl-info-grid"><article><b>🎯 Nur Ego</b><p>Keine Third-Person-Umschaltung mehr. WASD bewegt, Maus zielt, Linksklick feuert, Rechtsklick ADS, R lädt, SPACE springt, C duckt.</p></article><article><b>🔫 Lobby-Schießen</b><p>In der Lobby darfst du mit deinem Loadout schießen und die Ziele im Trainingsbereich treffen. Spieler- oder Bot-Schaden ist dort vollständig deaktiviert.</p></article><article><b>🗺️ Taktische Maps</b><p>Dustline, Harbor Yard und Metro Core sind eigenständige CS-artige Karten mit Mid, Long, Tunneln, Containern, Sites und Servicegängen.</p></article><article><b>🌐 Online</b><p>Online-Spieler werden nur angezeigt, wenn Map und Modus übereinstimmen. Ihre aktuelle Waffe ist direkt am Charakter sichtbar.</p></article><article><b>🔁 Waffengame</b><p>Jeder eigene Kill schaltet sofort die nächste Waffe der Runde frei. Die letzten Stufen sind Barrett, Katana und Messer.</p></article><article><b>⚙️ Performance</b><p>Reduzierte Pixelratio, weniger Shadow-Last und selteneres HUD-Rendering sorgen für flüssigere Bewegung.</p></article></div>`);}

  function openShop(){const s=state();showModal(`<div class="eskl-modal-head"><div><small>LOBBY SHOP</small><h2>Waffen & Versorgung</h2><p>${fmt(s.totalKills)} Kills · ${fmt(s.killTokens)} Kill-Punkte</p></div><button data-modal-close>×</button></div><div class="eskl-shop-tabs"><button class="active" data-shop-tab="weapons">Waffen</button><button data-shop-tab="supply">Versorgung</button><button data-shop-tab="repair">Reparatur / Level</button></div><div data-shop-body></div>`);UI.modal.querySelectorAll('[data-shop-tab]').forEach(b=>b.onclick=()=>{UI.modal.querySelectorAll('[data-shop-tab]').forEach(x=>x.classList.toggle('active',x===b));renderShopTab(b.dataset.shopTab);});renderShopTab('weapons');}
