  function bindShopActions(){UI.modal?.querySelectorAll('[data-buy-weapon]').forEach(b=>b.onclick=()=>{const w=WEAPON_MAP[b.dataset.buyWeapon],s=state();if(!w||s.totalKills<w.minKills||s.killTokens<w.cost)return toast('Noch nicht genug Kills/Kill-Punkte.','bad');s.killTokens-=w.cost;weaponState(w.id).owned=true;weaponState(w.id).durability=100;persist();refreshHeader();renderShopTab('weapons');toast(`${w.name} freigeschaltet.`,'good');});UI.modal?.querySelectorAll('[data-buy-supply]').forEach(b=>b.onclick=()=>{const s=state(),cost=Number(b.dataset.cost)||0,id=b.dataset.buySupply;if(s.killTokens<cost)return toast('Nicht genug Kill-Punkte.','bad');s.killTokens-=cost;s.inventory[id]=Number(s.inventory[id]||0)+1;persist();refreshHeader();renderShopTab('supply');toast('Gekauft.','good');});UI.modal?.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>{const id=b.dataset.repair,ws=weaponState(id),cost=Math.max(2,Math.ceil((100-ws.durability)/20)+ws.level),s=state();if(s.killTokens<cost)return toast('Nicht genug Kill-Punkte.','bad');s.killTokens-=cost;ws.durability=100;persist();refreshHeader();renderShopTab('repair');});UI.modal?.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const id=b.dataset.upgrade,ws=weaponState(id),cost=UPGRADE_COSTS[ws.level]||99999,s=state();if(ws.level>=10)return;if(s.killTokens<cost)return toast('Nicht genug Kill-Punkte.','bad');s.killTokens-=cost;ws.level++;persist();refreshHeader();renderShopTab('repair');});}
