  function mat(color,roughness=.86,metalness=.05){return new THREE.MeshStandardMaterial({color,roughness,metalness});}
  function addBox(s,{x=0,y=0,z=0,w=1,h=1,d=1,color=0x444444,material=null,solid=true,shot=true,cast=true,receive=true,name=''}){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material||mat(color));m.position.set(x,y+h/2,z);m.castShadow=cast&&!isTouch();m.receiveShadow=receive;m.name=name;s.scene.add(m);if(solid)addCollider(s,x,z,w,d,m,shot);else if(shot){m.userData.blockShot=true;s.shootables.push(m);}return m;}
  function addPlaneFloor(s,size,color){const g=new THREE.Mesh(new THREE.PlaneGeometry(size,size),mat(color,.96));g.rotation.x=-Math.PI/2;g.receiveShadow=true;s.scene.add(g);return g;}
