  function addPlace(s,id,x,z,color,label,kind='action',radius=4.8){const ring=new THREE.Mesh(new THREE.RingGeometry(3.2,4.2,40),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.62,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.055,z);s.scene.add(ring);const p=new THREE.PointLight(color,2.4,13);p.position.set(x,2.8,z);s.scene.add(p);addLabel(s,label,x,2.9,z,.9);s.places[id]={id,x,z,radius,label,kind};}
