    const cols=[0x1f6b82,0x8a3f32,0x5a6d32,0x785e28];[[ -24,-36,0],[ -15,-23,Math.PI/2],[ -4,-36,0],[8,-22,Math.PI/2],[18,-38,0],[ -28,26,Math.PI/2],[-13,36,0],[2,26,Math.PI/2],[16,39,0],[29,27,Math.PI/2]].forEach((r,i)=>addContainer(s,r[0],r[1],r[2],cols[i%cols.length]));
