    for(let z=-50;z<=50;z+=6){const a=new THREE.Mesh(new THREE.BoxGeometry(.16,.08,4.8),new THREE.MeshBasicMaterial({color:0x777b7d}));a.position.set(-7,.04,z);s.scene.add(a);const b=a.clone();b.position.x=7;s.scene.add(b);}addBox(s,{x:-7,z:0,w:.16,h:.08,d:118,color:0xa0a0a0,solid:false,shot:false});addBox(s,{x:7,z:0,w:.16,h:.08,d:118,color:0xa0a0a0,solid:false,shot:false});
