  function randomSpawn(s){const list=s?.spawns?.length?s.spawns:DEFAULT_MAP_SPAWNS.map(([x,y,z])=>new THREE.Vector3(x,y,z));return list[Math.floor(Math.random()*list.length)].clone();}
  function openModePicker(s,mapId){const m=MAPS[mapId];if(!m)return;showModal(`<div class="eskl-modal-head"><div><small>MAP AUSWÄHLEN</small><h2>${esc(m.name)}</h2><p>${esc(m.subtitle)}</p></div><button data-modal-close>×</button></div><div class="eskl-mode-grid"><button data-play="online-dm"><b>🌐 Online Deathmatch</b><small>Dein normales Loadout · echte Spieler auf dieser Map</small></button><button data-play="online-gg"><b>🌐 Online Waffengame</b><small>Kill → nächste Waffe · gleiche Map/gleicher Modus</small></button><button data-play="bot-dm"><b>🤖 Bot Deathmatch</b><small>Training gegen ${BOT_COUNT} Bots</small></button><button data-play="bot-gg"><b>🔁 Bot Waffengame</b><small>Waffenleiter gegen Bots</small></button></div>`);UI.modal.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{const v=b.dataset.play;closeModal();startCombat(mapId,v.includes('gg')?'gungame':'deathmatch',v.startsWith('online'));});}

  function bindWorldUi(s){
    UI.body.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useConsumable(s,b.dataset.use));
    UI.body.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>setSlot(s,b.dataset.slot));
    UI.body.querySelector('[data-reload]')?.addEventListener('click',()=>beginReload(s));
    UI.body.querySelector('[data-interact]')?.addEventListener('click',()=>interact(s));
    UI.body.querySelector('[data-staff-mod]')?.addEventListener('click',()=>openStaffMenu(s));
    UI.body.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='jump')jumpPlayer(s);else if(b.dataset.action==='crouch')toggleStance(s);});
    UI.body.querySelectorAll('[data-touch]').forEach(b=>{const k=b.dataset.touch;const set=v=>{UI.touch[k]=v;if(k==='fire'){UI.mouse.down=v;if(!v)s.shotHeld=false;}if(k==='ads')UI.mouse.ads=v;};for(const ev of ['pointerdown','touchstart'])b.addEventListener(ev,e=>{e.preventDefault();set(true);},{passive:false});for(const ev of ['pointerup','pointercancel','touchend','touchcancel'])b.addEventListener(ev,e=>{e.preventDefault();set(false);},{passive:false});});
  }
  function bindTouchLook(s,canvas){let pointer=null,lastX=0,lastY=0;canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.target?.closest?.('button'))return;pointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;try{canvas.setPointerCapture(pointer);}catch{}},{passive:true});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer||e.pointerType!=='touch'||UI.modal)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;s.yaw-=dx*.006;s.pitch=clamp(s.pitch-dy*.0048,-1.15,1.1);},{passive:true});const end=e=>{if(e.pointerId===pointer)pointer=null;};canvas.addEventListener('pointerup',end,{passive:true});canvas.addEventListener('pointercancel',end,{passive:true});}
  function resizeWorld(s){if(!s?.renderer||!s.wrap)return;const r=s.wrap.getBoundingClientRect(),w=Math.max(1,r.width),h=Math.max(1,r.height);s.renderer.setSize(w,h,false);s.camera.aspect=w/h;s.camera.updateProjectionMatrix();}
  function onPointerLockChange(){const s=UI.session;if(!s)return;if(document.pointerLockElement!==s.renderer?.domElement){UI.mouse.down=false;UI.mouse.ads=false;s.shotHeld=false;for(const k of Object.keys(UI.keys))if(/^Key[WASD]$|^Arrow/.test(k))UI.keys[k]=false;}}

  function loop(s){if(UI.session!==s)return;s.timer.update();const dt=Math.min(.05,Math.max(.001,s.timer.getDelta?.()||.016));s.worldTime+=dt;s.fpWeapon?.userData?.mixer?.update?.(dt);s.fpArmsMixer?.update?.(dt);advanceWeaponAnimation(s,dt);updateMovement(s,dt);if(s.mode==='combat'&&!s.online)updateBots(s,dt);if(s.online){syncOnlineWrite(s,performance.now());updateRemoteLerp(s,dt);}updateShooting(s,performance.now());updateCamera(s,dt);updateLobbyPrompt(s);updateHud(s);s.renderer.render(s.scene,s.camera);s.raf=requestAnimationFrame(()=>loop(s));}
  function advanceWeaponAnimation(s,dt){s.weaponKick=Math.max(0,(Number(s.weaponKick)||0)-dt*7.5);s.meleeSwing=Math.max(0,(Number(s.meleeSwing)||0)-dt*4.7);}
  function forwardFromYaw(yaw,out=new THREE.Vector3()){return out.set(-Math.sin(yaw),0,-Math.cos(yaw));}
  function moveInput(){return {f:(UI.keys.KeyW||UI.keys.ArrowUp||UI.touch.forward?1:0)-(UI.keys.KeyS||UI.keys.ArrowDown||UI.touch.back?1:0),r:(UI.keys.KeyD||UI.keys.ArrowRight||UI.touch.right?1:0)-(UI.keys.KeyA||UI.keys.ArrowLeft||UI.touch.left?1:0),run:!!(UI.keys.ShiftLeft||UI.keys.ShiftRight||UI.touch.run)};}
  function collides(s,x,z){const b=s.bounds||{minX:-71,maxX:71,minZ:-71,maxZ:71};if(x<b.minX||x>b.maxX||z<b.minZ||z>b.maxZ)return true;return s.collision.some(c=>x>c.minX&&x<c.maxX&&z>c.minZ&&z<c.maxZ);}
  function tryMove(s,dx,dz){const nx=s.pos.x+dx,nz=s.pos.z+dz;if(collides(s,nx,nz))return false;s.pos.x=nx;s.pos.z=nz;return true;}
  function updateMovement(s,dt){if(!s.alive||UI.modal)return;const inp=moveInput(),boost=performance.now()<s.speedBoostUntil?1.55:1,stanceMult=s.stance==='crouch'?.58:1,running=inp.f>0&&inp.run&&s.stance==='stand',speed=(running?RUN_SPEED:WALK_SPEED)*s.staff.speed*boost*stanceMult,len=Math.max(1,Math.hypot(inp.f,inp.r)),f=inp.f/len,r=inp.r/len,fw=forwardFromYaw(s.yaw),rx=Math.cos(s.yaw),rz=-Math.sin(s.yaw),mx=fw.x*f+rx*r,mz=fw.z*f+rz*r,dx=mx*speed*dt,dz=mz*speed*dt,ox=s.pos.x,oz=s.pos.z;
    if(isStaff()&&s.staff.fly){s.pos.x+=dx;s.pos.z+=dz;if(UI.keys.Space)s.pos.y+=speed*dt;if(UI.keys.ControlLeft||UI.keys.ControlRight)s.pos.y-=speed*dt;s.pos.y=clamp(s.pos.y,.1,80);s.verticalVelocity=0;s.onGround=false;}else{tryMove(s,dx,0);tryMove(s,0,dz);s.verticalVelocity-=18*dt;s.pos.y+=s.verticalVelocity*dt;if(s.pos.y<=0){s.pos.y=0;s.verticalVelocity=0;s.onGround=true;}else s.onGround=false;}
    s.moving=Math.hypot(s.pos.x-ox,s.pos.z-oz)>.002;s.running=s.moving&&running;s.bodyYaw=s.yaw;
  }
  function toggleStance(s){if(!s?.alive||s.staff.fly)return;s.stance=s.stance==='crouch'?'stand':'crouch';updateHud(s,true);}
  function jumpPlayer(s){if(!s?.alive||s.staff.fly||!s.onGround)return;if(s.stance==='crouch')s.stance='stand';s.verticalVelocity=6.3;s.onGround=false;}
  function updateCamera(s,dt){const eye=s.stance==='crouch'?1.08:1.60;s.camera.position.set(s.pos.x,s.pos.y+eye,s.pos.z);s.camera.rotation.order='YXZ';s.camera.rotation.y=s.yaw;s.camera.rotation.x=s.pitch;s.camera.rotation.z=0;const targetFov=UI.mouse.ads?54:72;s.camera.fov+=(targetFov-s.camera.fov)*Math.min(1,dt*13);s.camera.updateProjectionMatrix();if(s.fpArms)s.fpArms.visible=!s.staff.vanish;updateFpPresentation(s,dt);}

  function thirdPersonWeaponSize(w){if(!w)return .62;if(w.type==='pistol')return .47;if(w.type==='smg')return .54;if(w.id==='knife')return .48;if(w.type==='melee')return .65;return .73;}
  function holsteredWeaponSize(w){return thirdPersonWeaponSize(w)*.86;}
  function anchorHeldWeapon(ch,g,w){if(!g||!w)return;g.rotation.set(0,0,0);if(w.type==='pistol'){g.position.set(.18,1.12,-.25);g.rotation.set(-.08,.02,.06);}else if(w.type==='melee'){g.position.set(.20,1.03,-.25);g.rotation.set(w.id==='knife'?.15:-.25,.05,-.18);}else{g.position.set(.13,1.12,-.38);g.rotation.set(-.08,.02,.03);}}
  function anchorHolsteredWeapon(ch,g,w){if(!g||!w)return;if(w.slot==='sidearm'){g.position.set(.31,.78,.05);g.rotation.set(-Math.PI/2,0,.06);}else if(w.id==='knife'){g.position.set(-.30,.78,.05);g.rotation.set(-Math.PI/2,0,.1);}else if(w.id==='katana'||w.id==='baseball'){g.position.set(-.12,1.14,.18);g.rotation.set(-1.0,0,-.55);}else{g.position.set(0,1.05,.20);g.rotation.set(-.9,0,.06);}}
  function updateHeldWeaponPose(ch){if(ch?.heldWeapon)anchorHeldWeapon(ch,ch.heldWeapon,ch.heldWeapon.userData.weapon);}
  function updateHolsteredWeaponPoses(ch){for(const g of ch?.holsteredWeapons||[])anchorHolsteredWeapon(ch,g,g.userData.weapon);}
  function clearRemoteWeapons(ch){if(!ch)return;for(const child of [...ch.root.children])if(child.userData?.remoteLoadout||child.userData?.activeWeapon)ch.root.remove(child);ch.heldWeapon=null;ch.holsteredWeapons=[];}
  async function attachActiveWeapon(ch,id){const w=WEAPON_MAP[id];if(!w)return;clearRemoteWeapons(ch);const m=await makeWeaponModel(id,thirdPersonWeaponSize(w)),g=new THREE.Group();g.userData.activeWeapon=true;g.userData.remoteLoadout=true;g.userData.esklWeapon=true;g.userData.weapon=w;g.add(m);ch.root.add(g);ch.heldWeapon=g;anchorHeldWeapon(ch,g,w);}
  async function rebuildRemoteLoadout(ch,loadout,activeSlot,key){ch.root.userData.remoteLoadoutKey=key;clearRemoteWeapons(ch);for(const slot of SLOT_ORDER){const id=loadout[slot],w=WEAPON_MAP[id];if(!w)continue;const active=slot===activeSlot,m=await makeWeaponModel(id,active?thirdPersonWeaponSize(w):holsteredWeaponSize(w));if(ch.root.userData.remoteLoadoutKey!==key)return;const g=new THREE.Group();g.userData.remoteLoadout=true;g.userData.esklWeapon=true;g.userData.weapon=w;g.add(m);ch.root.add(g);if(active){ch.heldWeapon=g;anchorHeldWeapon(ch,g,w);}else{ch.holsteredWeapons.push(g);anchorHolsteredWeapon(ch,g,w);}}}

  async function fpArmsTemplate(){if(fpArmsTemplatePromise)return fpArmsTemplatePromise;fpArmsTemplatePromise=loader.loadAsync(FP_ARMS_ASSET).catch(err=>{fpArmsTemplatePromise=null;console.warn('Egoshoot.KL First-Person-Arme konnten nicht geladen werden:',err);return null;});return fpArmsTemplatePromise;}
  function fpArmsIdleForWeapon(w){if(!w)return 'guard_idle';if(w.id==='knife')return 'knife_idle';if(w.type==='melee')return 'guard_idle';return 'finger_gun_idle';}
