  async function ensureFpArms(s){if(!s||s.fpArms)return s?.fpArms||null;const build=++s.fpArmsBuildId,template=await fpArmsTemplate();if(!template?.scene||UI.session!==s||s.fpArmsBuildId!==build)return null;const raw=cloneSkeleton(template.scene);raw.traverse(o=>{if(o.isMesh||o.isSkinnedMesh){o.frustumCulled=false;o.renderOrder=996;for(const m of (Array.isArray(o.material)?o.material:[o.material]))if(m){m.depthTest=false;m.depthWrite=false;m.needsUpdate=true;}}});raw.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(raw),size=box.getSize(new THREE.Vector3()),scale=1.48/Math.max(.001,size.x,size.y,size.z);raw.scale.setScalar(scale);raw.rotation.y=Math.PI;raw.position.set(0,-.92,-.42);const group=new THREE.Group();group.name='egoshoot-first-person-arms';group.add(raw);s.camera.add(group);s.fpArms=group;s.fpArmsRaw=raw;s.fpArmsHand=raw.getObjectByName('hand.R_05')||raw.getObjectByName('handIK.R_049')||null;s.fpArmsMixer=new THREE.AnimationMixer(raw);s.fpArmsActions=new Map();for(const clip of template.animations||[]){const key=String(clip.name||'').replace(/^.*\|/,'').toLowerCase();s.fpArmsActions.set(key,s.fpArmsMixer.clipAction(clip));}playFpArms(s,fpArmsIdleForWeapon(WEAPON_MAP[activeWeaponId(s)]),true);return group;}
  function syncFpWeaponToHand(s,w){const g=s?.fpWeapon,hand=s?.fpArmsHand;if(!g||!hand)return false;hand.updateWorldMatrix?.(true,false);s.camera.updateWorldMatrix?.(true,false);const wp=new THREE.Vector3(),wq=new THREE.Quaternion(),cq=new THREE.Quaternion();hand.getWorldPosition(wp);hand.getWorldQuaternion(wq);s.camera.getWorldQuaternion(cq);const localPos=s.camera.worldToLocal(wp.clone()),localQ=cq.invert().multiply(wq),ahead=w?.type==='pistol'?.095:w?.type==='smg'?.12:w?.id==='knife'?.115:w?.type==='melee'?.14:.16;localPos.add(new THREE.Vector3(w?.id==='knife'?.015:0,ahead,0).applyQuaternion(localQ));const kick=Math.max(0,s.weaponKick||0),swing=Math.max(0,s.meleeSwing||0),phase=Math.sin((1-swing)*Math.PI);localPos.z+=kick*.035;if(w?.id==='knife')localPos.add(new THREE.Vector3(0,phase*.03,-phase*.20).applyQuaternion(localQ));g.position.lerp(localPos,.72);const grip=new THREE.Quaternion().setFromEuler(new THREE.Euler(Math.PI/2,w?.id==='knife'?.08:0,w?.type==='pistol'?.04:0)),targetQ=localQ.clone().multiply(grip);if(kick)targetQ.multiply(new THREE.Quaternion().setFromEuler(new THREE.Euler(kick*.16,0,0)));g.quaternion.slerp(targetQ,.76);return true;}
