  async function updateFpWeapon(s){if(!s)return;const build=(s.fpBuildId||0)+1;s.fpBuildId=build;if(s.fpWeapon){s.camera.remove(s.fpWeapon);s.fpWeapon=null;}await ensureFpArms(s);const id=activeWeaponId(s),w=WEAPON_MAP[id];if(!w){refreshFpArmsIdle(s);return;}if(s.gameMode!=='gungame'&&!weaponState(id).owned){refreshFpArmsIdle(s);return;}const model=await makeWeaponModel(id,fpModelSize(w)*.88);if(UI.session!==s||s.fpBuildId!==build)return;const pose=fpPose(w),g=new THREE.Group();g.add(model);g.position.copy(pose.pos);g.rotation.copy(pose.rot);g.userData.basePos=pose.pos.clone();g.userData.adsPos=pose.ads.clone();g.userData.baseRot=pose.rot.clone();if(model.userData.esklAnimations?.length){g.userData.mixer=new THREE.AnimationMixer(model);const clip=model.userData.esklAnimations.find(a=>/shoot|fire/i.test(a.name||''))||model.userData.esklAnimations[0];if(clip){g.userData.shootAction=g.userData.mixer.clipAction(clip);g.userData.shootAction.setLoop(THREE.LoopOnce,1);g.userData.shootAction.clampWhenFinished=true;}}s.camera.add(g);s.fpWeapon=g;s.currentSlot=w.slot;s.ammo[id]=Number.isFinite(s.ammo[id])?s.ammo[id]:(w.mag||0);refreshFpArmsIdle(s);syncFpWeaponToHand(s,w);updateHud(s,true);}
